-- Correction to the 2026-11-13 import. Source: "TABLA DE MERCADO 1028 - SUPER OFICIAL PROMMASA.xlsx". SHA256: edecbd5edd7d926801b45b1241599f1111e66f3e75b170515eac70f2c67e686c
-- The 11-13 import wrongly used STATUS-column-H OR STATUS-column-M to decide 'vendido'.
-- Client confirmed 2026-11-14 (final): only column M is the real sales record; column H is ignored.
-- Flips these 189 stalls back from vendido to disponible (they were vendido only per column H).
-- Skips rows currently separado/bloqueado: those are live app transactions.
-- Review before running. Not applied from this machine (no production credentials here).
begin;
lock table public.puestos in share row exclusive mode;
create temporary table _omitidos(codigo text, estado text) on commit drop;
insert into _omitidos select 'A-161', estado from public.puestos where codigo='A-161' and estado in ('separado','bloqueado');
update public.puestos set estado='disponible', version=version+1, actualizado_en=now() where codigo='A-161' and estado not in ('separado','bloqueado') and estado='vendido';
